{"cards": [{"node_code": "N_253c3f72c9c13633", "definition": "研究港口陆域内用于货物集散、临时存储及装卸作业的空间设施，包括货场、仓库、货棚及作业区的平面布置、结构构造与功能分区。", "boundary": "本节点聚焦于货物存储与作业空间的“静态”构造与布局。边界在于区分“存储设施”与“动态设备”（起重机、传送带归入传送与装卸设备）、“客运设施”（客运站归入客运站节点）。若内容涉及仓库内部物流自动化算法，侧重硬件结构归入本节点，侧重软件调度可关联智慧水运。", "includes": ["集装箱堆场、散货堆场、件杂货仓库的结构与布局", "货棚、雨棚等半封闭存储设施的构造", "装卸作业区的平面规划、地面承载与排水设计"], "excludes": ["具体的起重、传送机械设备的构造（归入传送与装卸设备）", "旅客候船室、客运站建筑（归入客运站）", "港口宏观选址与总体规划"], "sibling_distinctions": [{"other_code": "N_1b8b7c0cce9950d6", "rule": "本节点侧重货物存储与作业的空间设施（场、库、棚），兄弟节点侧重实现货物移动的机械设备（起重机、传送带等）。"}, {"other_code": "N_aa3ba2468f3d942b", "rule": "本节点针对货物存储与作业，兄弟节点针对旅客服务与候船设施，服务对象不同。"}], "cross_boundary_rule": "若内容涉及仓库内自动化立体库的机械结构，主挂载本节点；若涉及AGV调度系统，可关联智慧水运。"}, {"node_code": "N_108cf7e26fc025dd", "definition": "研究连接船舶与岸基、供人员及货物上下船使用的过渡性设施，包括引桥、栈桥、舷梯、跳板及活动登船廊道等构造。", "boundary": "本节点聚焦于“人/货上下船”的过渡通道设施。边界在于区分“登岸设备”与“码头主体”（码头平台归入码头节点）、“装卸设备”（起重机归入传送与装卸设备）。若内容涉及大型滚装船跳板的液压结构，归入本节点；若涉及码头前沿系缆桩，归入锚地泊位节点。", "includes": ["固定式或活动式引桥、栈桥的结构与构造", "旅客舷梯、滚装跳板、活动登船廊道的设计", "登岸设施与码头、船舶的接口构造"], "excludes": ["码头平台主体结构（归入码头）", "系泊设备如系缆桩、带缆孔（归入锚地、泊位及系泊设备）", "大型起重装卸机械（归入传送与装卸设备）"], "sibling_distinctions": [{"other_code": "N_3d41261b99ee8a4d", "rule": "本节点侧重连接船岸的过渡通道，兄弟节点侧重船舶停靠的主体平台结构。"}, {"other_code": "N_422c961200e72424", "rule": "本节点侧重人员/货物上下船的通道，兄弟节点侧重船舶系泊固定的设施（如系缆桩）。"}], "cross_boundary_rule": "若内容涉及登岸设施与码头结构的连接节点，主挂载本节点；若涉及码头整体结构，主挂载码头。"}, {"node_code": "N_1b8b7c0cce9950d6", "definition": "研究港口内用于货物垂直升降、水平输送及装卸作业的机械设备，包括起重机、输送机、叉车及自动化装卸系统的构造与选型。", "boundary": "本节点聚焦于“动态”货物处理机械。边界在于区分“装卸设备”与“存储设施”（仓库归入货场仓库节点）、“港内运输”（短驳车归入港内运输设备）。若内容涉及岸桥、门座起重机的结构力学，归入本节点；若涉及港口水平运输车辆，归入港内运输设备。", "includes": ["岸边集装箱起重机、门座起重机、抓斗等垂直装卸机械", "皮带输送机、斗式提升机等连续输送设备", "叉车、正面吊等场内装卸搬运机械"], "excludes": ["货物存储仓库与堆场结构（归入货场、仓库、货棚及装卸作业区）", "港口内部水平运输车辆如牵引车、集卡（归入港内运输设备）", "船舶甲板上的起重设备（归入船舶工程）"], "sibling_distinctions": [{"other_code": "N_253c3f72c9c13633", "rule": "本节点侧重执行装卸动作的机械设备，兄弟节点侧重货物存放与作业的空间设施。"}, {"other_code": "N_57c5b4745a0cbdb5", "rule": "本节点侧重垂直升降与短距离装卸机械，兄弟节点侧重港口内部长距离或水平运输车辆。"}], "cross_boundary_rule": "若内容涉及自动化码头中AGV与岸桥的协同作业硬件，主挂载本节点；若涉及AGV车辆本身，主挂载港内运输设备。"}]}
